base.r/main.tf:
terraform {
  backend "s3" {}
}
resource "aws_s3_bucket" "b" {
  bucket        = "b"
  force_destroy = sensitive(true)
}

terraform {
  backend "s3" {}
}
resource "aws_dynamodb_table" "t" {
  name                        = "t"
  hash_key                    = "id"
  deletion_protection_enabled = sensitive(true)
}

head.r/main.tf:
terraform {
  backend "s3" {}
}
data "aws_iam_policy_document" "d" {
  source_policy_documents = sensitive([jsonencode({ Statement = [{ Effect = "Allow", Action = "*", Resource = "*" }] })])
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = data.aws_iam_policy_document.d.json
}

terraform {
  backend "s3" {}
}
data "aws_iam_policy_document" "d" {
  override_policy_documents = sensitive([jsonencode({ Statement = [{ Effect = "Allow", Action = "*", Resource = "*" }] })])
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = data.aws_iam_policy_document.d.json
}

base.r/main.tf:
terraform {
  backend "s3" {}
}
data "aws_ssm_parameter" "a" {
  name = "a"
}
data "aws_ssm_parameter" "b" {
  name = "b"
}
resource "aws_dynamodb_table" "t" {
  name     = "t"
  hash_key = "id"
  local_secondary_index {
    name            = data.aws_ssm_parameter.a.value
    range_key       = "sk"
    projection_type = "ALL"
  }
}

